  var isChapterPage = document.body.getAttribute('data-page-type') === 'chapter';

  function getChapterHref(slug, reading) {
    var base = isChapterPage ? (slug + '.html') : ('chapters/' + slug + '.html');
    return reading ? (base + '?mode=reading') : base;
  }

  // 0. 深淺色主題切換（遵循 modern-web-guidance dark-mode-toggle 雙狀態規範）
  var metaColorScheme = document.querySelector('meta[name="color-scheme"]');
  var themeToggleBtn = document.getElementById('theme-toggle-btn');
  var darkMediaQuery = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;

  function getStoredScheme() {
    try {
      var val = window.localStorage.getItem('color-scheme');
      return (val === 'light' || val === 'dark') ? val : null;
    } catch (e) {
      return null;
    }
  }

  function getSystemScheme() {
    return (darkMediaQuery && darkMediaQuery.matches) ? 'dark' : 'light';
  }

  function getRenderedScheme() {
    return getStoredScheme() || getSystemScheme();
  }

  function syncThemeUI() {
    var stored = getStoredScheme();
    if (metaColorScheme) {
      metaColorScheme.content = stored || 'light dark';
    }
    var rendered = getRenderedScheme();
    document.documentElement.setAttribute('data-theme', rendered);
    if (themeToggleBtn) {
      var nextTarget = rendered === 'dark' ? '淺色模式' : '深色模式';
      themeToggleBtn.setAttribute('aria-label', '切換至' + nextTarget);
      themeToggleBtn.setAttribute('title', '目前為' + (rendered === 'dark' ? '深色' : '淺色') + '，點擊切換至' + nextTarget);
    }
  }

  if (themeToggleBtn) {
    themeToggleBtn.addEventListener('click', function () {
      var currentRendered = getRenderedScheme();
      var target = currentRendered === 'dark' ? 'light' : 'dark';
      var sys = getSystemScheme();
      try {
        if (target !== sys) {
          window.localStorage.setItem('color-scheme', target);
        } else {
          window.localStorage.removeItem('color-scheme');
        }
      } catch (e) {}
      if (metaColorScheme) {
        metaColorScheme.content = (target !== sys) ? target : 'light dark';
      }
      syncThemeUI();
    });
  }

  if (darkMediaQuery && typeof darkMediaQuery.addEventListener === 'function') {
    darkMediaQuery.addEventListener('change', function () {
      syncThemeUI();
    });
  }
  window.addEventListener('storage', function (e) {
    if (e.key === 'color-scheme') {
      syncThemeUI();
    }
  });
  syncThemeUI();

  // 一鍵複製程式碼按鈕
  var copyButtons = document.querySelectorAll('.copy-code-btn');
  for (var c = 0; c < copyButtons.length; c++) {
    (function (btn) {
      btn.addEventListener('click', function () {
        var container = btn.closest('.command-block, .pre-wrap');
        var codeEl = container ? container.querySelector('code') : null;
        if (!codeEl) return;
        var text = codeEl.textContent || '';
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text).then(function () {
            btn.textContent = '已複製 ✓';
            btn.setAttribute('data-copied', 'true');
            setTimeout(function () {
              btn.textContent = '複製';
              btn.removeAttribute('data-copied');
            }, 1800);
          }).catch(function () {});
        }
      });
    })(copyButtons[c]);
  }

  function isReadingMode() {
    try {
      var params = new URLSearchParams(window.location.search);
      var mode = params.get('mode');
      if (mode === 'reading' || mode === 'recording') return true;
      if (mode === 'normal') return false;
      return window.sessionStorage.getItem('codex_reading_mode') === '1';
    } catch (e) {
      return false;
    }
  }

  function setReadingMode(enabled) {
    try {
      if (enabled) {
        window.sessionStorage.setItem('codex_reading_mode', '1');
      } else {
        window.sessionStorage.removeItem('codex_reading_mode');
      }
    } catch (e) {}
    try {
      var url = new URL(window.location.href);
      if (enabled) {
        url.searchParams.set('mode', 'reading');
      } else {
        url.searchParams.delete('mode');
      }
      window.history.replaceState({}, '', url);
    } catch (e) {}
    applyReadingModeUI(enabled);
  }

  function applyReadingModeUI(enabled) {
    var siteRoot = document.getElementById('site-root');
    var toggleBtn = document.getElementById('recording-toggle-btn');
    var toggleText = document.getElementById('recording-toggle-text');
    if (siteRoot) {
      if (enabled) siteRoot.classList.add('recording-mode');
      else siteRoot.classList.remove('recording-mode');
    }
    if (toggleBtn) {
      toggleBtn.setAttribute('aria-pressed', enabled ? 'true' : 'false');
    }
    if (toggleText) {
      toggleText.textContent = enabled ? '退出閱讀模式' : '進入閱讀模式';
    }
    var chapterLinks = document.querySelectorAll('a[data-chapter-slug]');
    for (var i = 0; i < chapterLinks.length; i++) {
      var link = chapterLinks[i];
      var slug = link.getAttribute('data-chapter-slug');
      if (slug) {
        link.setAttribute('href', getChapterHref(slug, enabled));
      }
    }
  }

  function filterSearch(query, limitWhenEmpty) {
    var needle = (query || '').trim().toLowerCase();
    if (!needle) return limitWhenEmpty ? SEARCH_INDEX.slice(0, limitWhenEmpty) : [];
    var matches = [];
    SEARCH_INDEX.forEach(function (item) {
      var sections = item.sections.filter(function (section) {
        return (section.title + ' ' + section.text).toLowerCase().indexOf(needle) !== -1;
      });
      sections.forEach(function (section) {
        matches.push({ order: item.order, slug: item.slug, title: item.title, section: section });
      });
      if (!sections.length && (item.title + ' ' + item.summary).toLowerCase().indexOf(needle) !== -1) {
        matches.push(item);
      }
    });
    return matches.slice(0, 30);
  }

  function padOrder(n) {
    return String(n).padStart(2, '0');
  }

  function escapeHtml(str) {
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

